"use client";

import type { ReactNode } from "react";
import { Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

export type CalloutConnector = "arrow" | "elbow" | "line";
export type CalloutPlacement = "auto" | "top" | "bottom" | "left" | "right";
export type CalloutSide = "top" | "bottom" | "left" | "right";
export type CalloutVariant = "light" | "dark";

export interface CalloutPoint {
  x: number;
  y: number;
}

export interface CalloutRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** Target the callout points at: a point or a rectangle in composition pixels. */
export type CalloutTarget = CalloutPoint | CalloutRect;

export interface CalloutAnnotationProps {
  /** Headline of the label card. */
  label?: string;
  /** Smaller supporting line under the label. */
  sublabel?: string;
  /** Point `{x, y}` or rect `{x, y, width, height}` in composition pixels. */
  target?: CalloutTarget;
  /** Connector shape drawn from the card to the target. */
  connector?: CalloutConnector;
  /** Which side of the target the card sits on. `auto` picks the roomiest side; explicit sides flip when cramped. */
  placement?: CalloutPlacement;
  /** Connector, arrowhead and highlight color. */
  accentColor?: string;
  /** Card + text palette. */
  variant?: CalloutVariant;
  /** Gap in px between the target and the label card. */
  distance?: number;
  /** Sideways shift of the card along the target edge — gives arrows their diagonal and elbows their corner. */
  lateralOffset?: number;
  /** Gap in px between the arrow tip and the target. */
  targetPadding?: number;
  /** Draw a rounded accent outline + soft fill around rect targets. */
  highlight?: boolean;
  /** Frame (absolute) at which the callout starts entering. */
  enterAt?: number;
  /** Frame (absolute) at which the callout fades out. Omit to keep it on screen. */
  exitAt?: number;
  /** Render the built-in Acme payments dashboard in a browser window beneath the overlay. */
  showDemoUi?: boolean;
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  'Inter, var(--font-geist-sans), -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
const MONO_FAMILY =
  "'JetBrains Mono', var(--font-geist-mono), ui-monospace, SFMono-Regular, Menlo, monospace";

/** Frames the connector takes to draw in. */
export const CONNECTOR_DRAW_FRAMES = 12;
/** Local frame at which the label card starts fading + rising. */
export const CARD_ENTER_START = 10;
/** Frames the exit fade takes. */
export const EXIT_FRAMES = 10;

/** Per-variant snap-cn palette for the label card. */
export const CALLOUT_PALETTES: Record<
  CalloutVariant,
  { card: string; border: string; text: string; muted: string; shadow: string }
> = {
  light: {
    card: "#FFFFFF",
    border: "#E4E7EC",
    text: "#101828",
    muted: "#667085",
    shadow: "0 4px 14px rgba(16,24,40,0.08)",
  },
  dark: {
    card: "#141417",
    border: "#26272B",
    text: "#FAFAFA",
    muted: "#A1A1AA",
    shadow: "0 8px 24px rgba(0,0,0,0.4)",
  },
};

/** Default demo target: the "Reconcile" button of the built-in dashboard at 1280x720. */
export const DEMO_TARGET: CalloutRect = {
  x: 965,
  y: 120,
  width: 148,
  height: 36,
};

export function isRect(target: CalloutTarget): target is CalloutRect {
  return (
    typeof (target as CalloutRect).width === "number" &&
    typeof (target as CalloutRect).height === "number"
  );
}

/** Bounding box of the target (zero-size box for point targets). */
export function targetBounds(target: CalloutTarget): CalloutRect {
  if (isRect(target)) return target;
  return { x: target.x, y: target.y, width: 0, height: 0 };
}

/** Free space between the target's bounds and each composition edge. */
export function sideClearances(
  target: CalloutTarget,
  viewportWidth: number,
  viewportHeight: number,
): Record<CalloutSide, number> {
  const b = targetBounds(target);
  return {
    top: b.y,
    bottom: viewportHeight - (b.y + b.height),
    left: b.x,
    right: viewportWidth - (b.x + b.width),
  };
}

export const OPPOSITE_SIDE: Record<CalloutSide, CalloutSide> = {
  top: "bottom",
  bottom: "top",
  left: "right",
  right: "left",
};

/**
 * Resolve `auto` to the side with the most clearance; flip an explicit side
 * to its opposite when it lacks `needed` px and the opposite has more room.
 */
export function resolvePlacement(
  target: CalloutTarget,
  placement: CalloutPlacement,
  viewportWidth: number,
  viewportHeight: number,
  needed: number,
): CalloutSide {
  const c = sideClearances(target, viewportWidth, viewportHeight);
  if (placement !== "auto") {
    const opposite = OPPOSITE_SIDE[placement];
    if (c[placement] < needed && c[opposite] > c[placement]) return opposite;
    return placement;
  }
  const order: CalloutSide[] = ["bottom", "top", "left", "right"];
  let best: CalloutSide = "bottom";
  for (const side of order) {
    if (c[side] > c[best]) best = side;
  }
  return best;
}

/** Point on the target's edge facing the card (the point itself for point targets). */
export function targetAnchor(
  target: CalloutTarget,
  side: CalloutSide,
): CalloutPoint {
  if (!isRect(target)) return { x: target.x, y: target.y };
  const cx = target.x + target.width / 2;
  const cy = target.y + target.height / 2;
  switch (side) {
    case "top":
      return { x: cx, y: target.y };
    case "bottom":
      return { x: cx, y: target.y + target.height };
    case "left":
      return { x: target.x, y: cy };
    case "right":
      return { x: target.x + target.width, y: cy };
  }
}

/** Arrow tip: the anchor pushed `pad` px away from the target, toward the card. */
export function connectorTip(
  anchor: CalloutPoint,
  side: CalloutSide,
  pad: number,
): CalloutPoint {
  switch (side) {
    case "top":
      return { x: anchor.x, y: anchor.y - pad };
    case "bottom":
      return { x: anchor.x, y: anchor.y + pad };
    case "left":
      return { x: anchor.x - pad, y: anchor.y };
    case "right":
      return { x: anchor.x + pad, y: anchor.y };
  }
}

/** Where the connector meets the card (the card is anchored just beyond it). */
export function cardAnchor(
  tip: CalloutPoint,
  side: CalloutSide,
  distance: number,
  lateral: number,
): CalloutPoint {
  switch (side) {
    case "top":
      return { x: tip.x + lateral, y: tip.y - distance };
    case "bottom":
      return { x: tip.x + lateral, y: tip.y + distance };
    case "left":
      return { x: tip.x - distance, y: tip.y + lateral };
    case "right":
      return { x: tip.x + distance, y: tip.y + lateral };
  }
}

export function polylineLength(points: CalloutPoint[]): number {
  let length = 0;
  for (let i = 1; i < points.length; i++) {
    length += Math.hypot(
      points[i].x - points[i - 1].x,
      points[i].y - points[i - 1].y,
    );
  }
  return length;
}

/** Point on a quadratic Bezier at parameter t in [0, 1]. */
export function quadPoint(
  p0: CalloutPoint,
  control: CalloutPoint,
  p1: CalloutPoint,
  t: number,
): CalloutPoint {
  const u = 1 - t;
  return {
    x: u * u * p0.x + 2 * u * t * control.x + t * t * p1.x,
    y: u * u * p0.y + 2 * u * t * control.y + t * t * p1.y,
  };
}

/** Numeric arc length of a quadratic Bezier (polyline approximation). */
export function quadLength(
  p0: CalloutPoint,
  control: CalloutPoint,
  p1: CalloutPoint,
  samples = 32,
): number {
  let length = 0;
  let prev = p0;
  for (let i = 1; i <= samples; i++) {
    const pt = quadPoint(p0, control, p1, i / samples);
    length += Math.hypot(pt.x - prev.x, pt.y - prev.y);
    prev = pt;
  }
  return length;
}

export interface ConnectorGeometry {
  /** SVG path data from the card to the target tip. */
  d: string;
  /** Total path length (drives the stroke-dash draw-on). */
  length: number;
  /** Degrees the arrowhead is rotated at the tip (0 = pointing +x). */
  endAngle: number;
}

function angleDeg(dx: number, dy: number): number {
  return (Math.atan2(dy, dx) * 180) / Math.PI;
}

/**
 * Pure connector geometry: path data, total length, and the arrowhead angle
 * at the tip, for each connector style.
 */
export function connectorGeometry(
  start: CalloutPoint,
  tip: CalloutPoint,
  connector: CalloutConnector,
  side: CalloutSide,
): ConnectorGeometry {
  const vertical = side === "top" || side === "bottom";
  if (connector === "elbow") {
    const corner = vertical
      ? { x: tip.x, y: start.y }
      : { x: start.x, y: tip.y };
    const points = [start, corner, tip];
    const lastDx = tip.x - corner.x;
    const lastDy = tip.y - corner.y;
    const hasLast = Math.hypot(lastDx, lastDy) > 0.001;
    return {
      d: `M ${start.x} ${start.y} L ${corner.x} ${corner.y} L ${tip.x} ${tip.y}`,
      length: polylineLength(points),
      endAngle: hasLast
        ? angleDeg(lastDx, lastDy)
        : angleDeg(corner.x - start.x, corner.y - start.y),
    };
  }
  if (connector === "line") {
    return {
      d: `M ${start.x} ${start.y} L ${tip.x} ${tip.y}`,
      length: polylineLength([start, tip]),
      endAngle: angleDeg(tip.x - start.x, tip.y - start.y),
    };
  }
  // "arrow": gentle quadratic curve that leaves the card straight, then
  // bends into the target. Collapses to a straight line when aligned.
  const control = vertical
    ? { x: start.x, y: start.y + (tip.y - start.y) * 0.65 }
    : { x: start.x + (tip.x - start.x) * 0.65, y: start.y };
  return {
    d: `M ${start.x} ${start.y} Q ${control.x} ${control.y} ${tip.x} ${tip.y}`,
    length: quadLength(start, control, tip),
    endAngle: angleDeg(tip.x - control.x, tip.y - control.y),
  };
}

/** #RGB / #RRGGBB → rgba(). Falls back to accent blue on bad input. */
export function hexToRgba(hex: string, alpha: number): string {
  const raw = hex.replace("#", "").trim();
  const full =
    raw.length === 3
      ? raw
          .split("")
          .map((c) => c + c)
          .join("")
      : raw;
  if (!/^[0-9a-fA-F]{6}$/.test(full)) {
    return `rgba(38,109,240,${alpha})`;
  }
  const r = Number.parseInt(full.slice(0, 2), 16);
  const g = Number.parseInt(full.slice(2, 4), 16);
  const b = Number.parseInt(full.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

const CARD_TRANSLATE: Record<CalloutSide, string> = {
  top: "translate(-50%, -100%)",
  bottom: "translate(-50%, 0%)",
  left: "translate(-100%, -50%)",
  right: "translate(0%, -50%)",
};

/** Small gap between the connector start and the card edge. */
const CARD_GAP = 6;

const DEMO_ROWS = [
  {
    id: "PAY-2411",
    vendor: "Globex Media",
    amount: "$4,820.00",
    status: "Matched",
  },
  {
    id: "PAY-2412",
    vendor: "Initech Cloud",
    amount: "$1,290.50",
    status: "Matched",
  },
  {
    id: "PAY-2413",
    vendor: "Vandelay Imports",
    amount: "$9,301.20",
    status: "Pending",
  },
  {
    id: "PAY-2414",
    vendor: "Acme Retail",
    amount: "$612.00",
    status: "Matched",
  },
];

/* --- Local light browser chrome (self-contained; callout only ever needs
   this one fixed light config). --- */
const BROWSER_LIGHT = {
  chrome: "#FFFFFF",
  canvas: "#FAFAFA",
  border: "#E4E7EC",
  text: "#101828",
  muted: "#667085",
  urlField: "#FAFAFA",
};
const TRAFFIC_LIGHTS = ["#FF5F57", "#FEBC2E", "#28C840"];
const URL_TYPE_START_FRAME = 8;
const URL_TYPE_FRAMES = 20;

/** How many characters of the URL are visible at `frame`. */
function typedUrlCount(frame: number, urlLength: number): number {
  if (urlLength <= 0) return 0;
  const progress = (frame - URL_TYPE_START_FRAME) / URL_TYPE_FRAMES;
  return Math.max(0, Math.min(urlLength, Math.floor(progress * urlLength)));
}

/** Solid while typing, then a 24-frame on/off blink. */
function caretOpacity(frame: number, typing: boolean): number {
  if (typing) return 1;
  return Math.floor(frame / 12) % 2 === 0 ? 1 : 0;
}

function BrowserFavicon() {
  return (
    <svg width={14} height={14} viewBox="0 0 14 14" fill="none" aria-hidden>
      <rect width={14} height={14} rx={4} fill="#266DF0" />
      <circle cx={7} cy={7} r={2.6} fill="#FFFFFF" />
    </svg>
  );
}

function LockIcon({ color }: { color: string }) {
  return (
    <svg width={11} height={11} viewBox="0 0 12 12" fill="none" aria-hidden>
      <rect
        x={2}
        y={5}
        width={8}
        height={5.5}
        rx={1.5}
        stroke={color}
        strokeWidth={1.2}
      />
      <path
        d="M4 5V3.8a2 2 0 0 1 4 0V5"
        stroke={color}
        strokeWidth={1.2}
        strokeLinecap="round"
      />
    </svg>
  );
}

function NavArrow({ color, back }: { color: string; back?: boolean }) {
  return (
    <svg
      width={14}
      height={14}
      viewBox="0 0 14 14"
      fill="none"
      aria-hidden
      style={{ rotate: back ? "0deg" : "180deg" }}
    >
      <path
        d="M8.5 3L4.5 7L8.5 11"
        stroke={color}
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** Fixed 1000×620 light browser window with a typed URL + rise entrance. */
function DemoBrowserFrame({
  url,
  tabTitle,
  children,
}: {
  url: string;
  tabTitle: string;
  children: ReactNode;
}) {
  const frame = useCurrentFrame();
  const palette = BROWSER_LIGHT;
  const visibleChars = typedUrlCount(frame, url.length);
  const typing = frame >= URL_TYPE_START_FRAME && visibleChars < url.length;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: FONT_FAMILY,
      }}
    >
      <div
        style={{
          width: 1000,
          height: 620,
          borderRadius: 10,
          backgroundColor: palette.chrome,
          border: `1px solid ${palette.border}`,
          boxShadow: "0 12px 40px rgba(16,24,40,0.12)",
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          opacity: interpolate(frame, [0, 14], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }),
          translate: interpolate(frame, [0, 18], ["0px 16px", "0px 0px"], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          }),
        }}
      >
        {/* Chrome bar: traffic lights, tab, navigation, URL field */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 14,
            height: 46,
            padding: "0 14px",
            backgroundColor: palette.chrome,
            borderBottom: `1px solid ${palette.border}`,
            flexShrink: 0,
          }}
        >
          <div style={{ display: "flex", gap: 7, flexShrink: 0 }}>
            {TRAFFIC_LIGHTS.map((color) => (
              <div
                key={color}
                style={{
                  width: 11,
                  height: 11,
                  borderRadius: 999,
                  backgroundColor: color,
                }}
              />
            ))}
          </div>

          {/* Active tab */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              padding: "6px 12px",
              borderRadius: 8,
              backgroundColor: palette.urlField,
              border: `1px solid ${palette.border}`,
              maxWidth: 240,
              flexShrink: 0,
            }}
          >
            <div style={{ display: "flex", flexShrink: 0 }}>
              <BrowserFavicon />
            </div>
            <div
              style={{
                fontSize: 12.5,
                fontWeight: 500,
                letterSpacing: "-0.01em",
                color: palette.text,
                whiteSpace: "nowrap",
                overflow: "hidden",
                textOverflow: "ellipsis",
              }}
            >
              {tabTitle}
            </div>
          </div>

          <div
            style={{ display: "flex", gap: 10, flexShrink: 0, opacity: 0.9 }}
          >
            <NavArrow color={palette.muted} back />
            <NavArrow color={palette.muted} />
          </div>

          {/* URL field */}
          <div
            style={{
              flex: 1,
              display: "flex",
              alignItems: "center",
              gap: 8,
              height: 30,
              padding: "0 12px",
              borderRadius: 8,
              backgroundColor: palette.urlField,
              border: `1px solid ${palette.border}`,
              minWidth: 0,
            }}
          >
            <LockIcon color={palette.muted} />
            <div
              style={{
                display: "flex",
                alignItems: "center",
                fontSize: 13,
                fontFamily: MONO_FAMILY,
                color: palette.muted,
                whiteSpace: "pre",
                overflow: "hidden",
              }}
            >
              <span>{url.slice(0, visibleChars)}</span>
              <span
                style={{
                  width: 1.5,
                  height: 14,
                  marginLeft: 2,
                  borderRadius: 1,
                  backgroundColor: palette.text,
                  opacity: caretOpacity(frame, typing),
                }}
              />
            </div>
          </div>
        </div>

        {/* Page content */}
        <div
          style={{
            flex: 1,
            position: "relative",
            minHeight: 0,
            backgroundColor: palette.canvas,
            overflow: "hidden",
          }}
        >
          {children}
        </div>
      </div>
    </div>
  );
}

/** Built-in Acme payments dashboard inside a browser window (demo backdrop). */
function DemoDashboard({ speed = 1 }: { speed?: number }) {
  const frame = useCurrentFrame() * speed;
  const palette = CALLOUT_PALETTES.light;

  return (
    <DemoBrowserFrame url="app.acme.dev/payments" tabTitle="Acme — Payments">
      <div
        style={{
          position: "absolute",
          inset: 0,
          padding: "22px 26px",
          fontFamily: FONT_FAMILY,
          boxSizing: "border-box",
        }}
      >
        <div
          style={{
            fontSize: 17,
            fontWeight: 600,
            letterSpacing: "-0.01em",
            color: palette.text,
          }}
        >
          Payments
        </div>
        <div style={{ fontSize: 12, color: palette.muted, marginTop: 4 }}>
          128 payouts · March
        </div>

        {/* Actions — the primary button is the default callout target. */}
        <div
          style={{
            position: "absolute",
            top: 22,
            right: 26,
            display: "flex",
            gap: 8,
          }}
        >
          <div
            style={{
              height: 36,
              padding: "0 14px",
              borderRadius: 8,
              border: `1px solid ${palette.border}`,
              backgroundColor: "#FFFFFF",
              color: palette.text,
              fontSize: 13,
              fontWeight: 500,
              display: "flex",
              alignItems: "center",
              boxSizing: "border-box",
            }}
          >
            Export
          </div>
          <div
            style={{
              width: 148,
              height: 36,
              borderRadius: 8,
              backgroundColor: "#266DF0",
              color: "#FFFFFF",
              fontSize: 13,
              fontWeight: 600,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxSizing: "border-box",
            }}
          >
            Reconcile
          </div>
        </div>

        {/* Payouts table */}
        <div
          style={{
            marginTop: 18,
            backgroundColor: "#FFFFFF",
            border: `1px solid ${palette.border}`,
            borderRadius: 10,
            overflow: "hidden",
            opacity: interpolate(frame, [14, 26], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }),
          }}
        >
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "120px 1fr 130px 100px",
              gap: 12,
              padding: "10px 16px",
              borderBottom: `1px solid ${palette.border}`,
              fontSize: 11,
              fontWeight: 500,
              letterSpacing: "0.04em",
              textTransform: "uppercase",
