            }}
          >
            <div>Payout</div>
            <div>Vendor</div>
            <div>Amount</div>
            <div>Status</div>
          </div>
          {DEMO_ROWS.map((row, i) => {
            const matched = row.status === "Matched";
            const statusColor = matched ? "#12B76A" : "#F79009";
            return (
              <div
                key={row.id}
                style={{
                  display: "grid",
                  gridTemplateColumns: "120px 1fr 130px 100px",
                  gap: 12,
                  alignItems: "center",
                  padding: "11px 16px",
                  borderBottom:
                    i < DEMO_ROWS.length - 1
                      ? `1px solid ${palette.border}`
                      : "none",
                  opacity: interpolate(
                    frame,
                    [18 + i * 4, 30 + i * 4],
                    [0, 1],
                    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
                  ),
                  translate: interpolate(
                    frame,
                    [18 + i * 4, 32 + i * 4],
                    ["0px 6px", "0px 0px"],
