                >
                  {row.status}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </DemoBrowserFrame>
  );
}

export function CalloutAnnotation({
  label = "One-click reconciliation",
  sublabel = "",
  target = DEMO_TARGET,
  connector = "arrow",
  placement = "auto",
  accentColor = "#266DF0",
  variant = "light",
  distance = 110,
  lateralOffset = 0,
  targetPadding = 8,
  highlight = true,
  enterAt = 0,
  exitAt,
  showDemoUi = false,
  speed = 1,
  className,
}: CalloutAnnotationProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const palette = CALLOUT_PALETTES[variant] ?? CALLOUT_PALETTES.light;

  // Local, speed-scaled clock. Clamped interpolations keep everything
  // hidden before enterAt without extra branches.
  const t = (frame - enterAt) * speed;

  const side = resolvePlacement(
    target,
    placement,
    width,
    height,
    distance + 140,
  );
  const anchor = targetAnchor(target, side);
  const tip = connectorTip(anchor, side, targetPadding);
  const start = cardAnchor(tip, side, distance, lateralOffset);
  const geometry = connectorGeometry(start, tip, connector, side);

  const draw = interpolate(t, [0, CONNECTOR_DRAW_FRAMES], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const headOpacity = interpolate(draw, [0.7, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const cardOpacity = interpolate(
    t,
    [CARD_ENTER_START, CARD_ENTER_START + 12],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
  );
  const cardRise = interpolate(
    t,
    [CARD_ENTER_START, CARD_ENTER_START + 14],
    [10, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    },
  );
  const exitOpacity =
    exitAt === undefined || exitAt < 0
      ? 1
      : interpolate((frame - exitAt) * speed, [0, EXIT_FRAMES], [1, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

  const rect = isRect(target) ? target : null;
  const showArrowhead = connector !== "line";

  // Card position: anchored just beyond the connector start, on the card side.
  const cardPos = {
    x:
      start.x + (side === "left" ? -CARD_GAP : side === "right" ? CARD_GAP : 0),
    y:
      start.y + (side === "top" ? -CARD_GAP : side === "bottom" ? CARD_GAP : 0),
  };

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        fontFamily: FONT_FAMILY,
      }}
    >
      {showDemoUi ? <DemoDashboard speed={speed} /> : null}

      <div style={{ position: "absolute", inset: 0, opacity: exitOpacity }}>
        <svg
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          fill="none"
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          {rect && highlight ? (
            <rect
              x={rect.x - 5}
              y={rect.y - 5}
              width={rect.width + 10}
              height={rect.height + 10}
              rx={8}
              stroke={accentColor}
              strokeWidth={1.5}
              fill={hexToRgba(accentColor, 0.06)}
              opacity={draw}
            />
          ) : null}
          <path
            d={geometry.d}
            stroke={accentColor}
            strokeWidth={1.5}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray={geometry.length}
            strokeDashoffset={geometry.length * (1 - draw)}
          />
          {showArrowhead ? (
            <g
              transform={`translate(${tip.x} ${tip.y}) rotate(${geometry.endAngle})`}
              opacity={headOpacity}
            >
              <path
                d="M -7 -4.5 L 0 0 L -7 4.5"
                stroke={accentColor}
                strokeWidth={1.5}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </g>
          ) : null}
        </svg>

        {/* Label card */}
        <div
          style={{
            position: "absolute",
            left: cardPos.x,
            top: cardPos.y,
            transform: `${CARD_TRANSLATE[side]} translateY(${cardRise}px)`,
            opacity: cardOpacity,
            backgroundColor: palette.card,
            border: `1px solid ${palette.border}`,
            borderRadius: 8,
            boxShadow: palette.shadow,
            padding: "10px 14px",
            maxWidth: 300,
          }}
        >
          <div
            style={{
              fontSize: 14,
              fontWeight: 600,
              letterSpacing: "-0.01em",
              lineHeight: 1.3,
              color: palette.text,
              whiteSpace: "nowrap",
            }}
          >
            {label}
          </div>
          {sublabel ? (
            <div
              style={{
                fontSize: 12,
                lineHeight: 1.45,
                color: palette.muted,
                marginTop: 3,
              }}
            >
              {sublabel}
            </div>
          ) : null}
        </div>
      </div>
    </div>
  );
}
